{"warehouses":{"east":{"gear":12,"seal":5},"west":{"gear":9,"seal":12},"overflow":{"gear":0,"seal":0}}}
// An overnight shortage and an operator rehearsal share the same runner.
proc rehearsal() {
    let attempts: int = 0;
    transaction {
        set attempts = attempts + 1;
        fulfill("practice", "gear", 1, "seal", 1, "east", "west");
        pause "rehearsal:before-abort";
        assert false;
    } recover (failure) {
        emit "rehearsal_reverted" { attempts: attempts; reason: code(failure); };
        pause code(failure);
    }
}

proc main() {
    reserve("safety", "east", "gear", 3);
    rehearsal();
    fulfill("alpha", "gear", 6, "seal", 6, "east", "west");
    pause "dispatch:after-alpha";
    fulfill("beta", "gear", 5, "seal", 3, "west", "east");
    fulfill("gamma", "gear", 8, "seal", 8, "east", "west");
    release("safety", 3);
    fulfill("delta", "gear", 4, "seal", 2, "east", "west");
    emit "closing" {
        east_gear: available("east", "gear");
        west_gear: available("west", "gear");
    };
}
----
proc rehearsal() {
    transaction {
        dispatch_order("drill", "gear", 2, "seal", 1, "east", "west");
        pause "operator:abort";
        assert false;
    } recover(e) {
        emit "rehearsal_reverted" {reason:code(e);};
        pause "operator:recovered";
    }
}

proc main() {
    rehearsal();
    dispatch_order("drill", "gear", 2, "seal", 1, "west", "east");
    dispatch_order("alpha", "gear", 6, "seal", 4, "east", "west");
    dispatch_order("beta", "gear", 5, "seal", 3, "east", "west");
    dispatch_order("orphan", "gear", 3, "seal", 2, "east", "west");
    dispatch_order("blocked", "gear", 2, "seal", 2, "east", "west");
    dispatch_order("gamma", "gear", 100, "seal", 100, "east", "west");
    dispatch_order("alpha", "gear", 6, "seal", 4, "west", "east");
    emit "closing" {east_gear:available("east","gear"); west_gear:available("west","gear");};
}
