"""Diagnostics and control-flow exceptions."""

EXIT_CODES = {
    "SYNTAX": 2, "STATIC": 3, "DOMAIN": 4, "RUNTIME": 5,
    "INPUT": 6, "IO": 7, "CHECKPOINT": 8,
}


class StockroomError(Exception):
    """A reportable failure. DOMAIN instances use the DomainError subclass."""

    def __init__(self, category, message, loc=None, stack=None, code=None):
        super().__init__(message)
        self.category = category
        self.message = message or category
        self.loc = loc
        self.stack = list(stack) if stack is not None else None
        self.code = code

    def diagnostic(self):
        out = {"error": self.category, "message": self.message}
        if self.loc is not None:
            source, line, column = self.loc
            out["file"] = source.display
            out["line"] = line
            out["column"] = column
        if self.stack is not None:
            out["stack"] = self.stack
        if self.code is not None:
            out["code"] = self.code
        return out

    @property
    def exit_code(self):
        return EXIT_CODES[self.category]


class DomainError(StockroomError):
    """Recoverable inventory/assert/carrier failure."""

    def __init__(self, code, message, loc, stack):
        super().__init__("DOMAIN", message, loc, stack, code)


class PauseExit(BaseException):
    """Successful durable suspension; never caught by `recover`."""

    def __init__(self, label):
        super().__init__(label)
        self.label = label

"""Lexer, parser and static checker for the Stockroom language."""
import json

from .errors import StockroomError


class SourceFile:
    def __init__(self, display, role, text):
        self.display = display
        self.role = role
        self.text = text


KEYWORDS = frozenset((
    "proc", "let", "set", "if", "else", "while", "transaction", "recover",
    "break", "continue", "return", "assert", "emit", "receive", "move",
    "reserve", "release", "ship", "int", "bool", "string", "true", "false",
    "pause", "record_delivery",
))

TYPES = ("int", "bool", "string")

# name -> (parameter types, result type)
BUILTINS = {
    "onhand": (("string", "string"), "int"),
    "available": (("string", "string"), "int"),
    "remaining": (("string",), "int"),
    "len": (("string",), "int"),
    "code": (("error",), "string"),
    "carrier_send": (("string", "string", "string", "int", "string", "int"), "string"),
    "carrier_receipt": (("string",), "string"),
    "carrier_warehouse": (("string",), "string"),
    "carrier_matches": (("string", "string", "string", "int", "string", "int"), "bool"),
    "delivered": (("string",), "bool"),
}

TWO_CHAR_OPS = ("==", "!=", "<=", ">=", "&&", "||")
ONE_CHAR_OPS = "(){},;:=<>+-*/%!"
WHITESPACE = " \t\r\n\f\v"


def syntax(source, line, col, message):
    return StockroomError("SYNTAX", message, (source, line, col))


def static(loc, message):
    return StockroomError("STATIC", message, loc)


class Token:
    __slots__ = ("kind", "value", "loc")

    def __init__(self, kind, value, loc):
        self.kind = kind      # name, kw, int, str, op, eof
        self.value = value
        self.loc = loc


def decode_source(source_display, role, data):
    try:
        return SourceFile(source_display, role, data.decode("utf-8"))
    except UnicodeDecodeError as exc:
        prefix = data[:exc.start].decode("utf-8", "replace")
        line = prefix.count("\n") + 1
        col = len(prefix) - (prefix.rfind("\n") + 1) + 1
        raise syntax(SourceFile(source_display, role, ""), line, col,
                     "Source is not valid UTF-8") from None


def tokenize(source):
    text = source.text
    n = len(text)
    i = 0
    line = 1
    line_start = 0
    tokens = []
    while True:
        while i < n:
            c = text[i]
            if c in WHITESPACE:
                if c == "\n":
                    line += 1
                    line_start = i + 1
                i += 1
            elif c == "/" and i + 1 < n and text[i + 1] == "/":
                while i < n and text[i] != "\n":
                    i += 1
            else:
                break
        col = i - line_start + 1
        loc = (source, line, col)
        if i >= n:
            tokens.append(Token("eof", None, loc))
            return tokens
        c = text[i]
        if c.isascii() and (c.isalpha() or c == "_"):
            j = i + 1
            while j < n and text[j].isascii() and (text[j].isalnum() or text[j] == "_"):
                j += 1
            word = text[i:j]
            tokens.append(Token("kw" if word in KEYWORDS else "name", word, loc))
            i = j
        elif "0" <= c <= "9":
            j = i + 1
            while j < n and "0" <= text[j] <= "9":
                j += 1
            tokens.append(Token("int", int(text[i:j]), loc))
            i = j
        elif c == '"':
            j = i + 1
            while True:
                if j >= n:
                    raise syntax(source, line, col, "Unterminated string")
                d = text[j]
                if d == '"':
                    break
                if d == "\\":
                    if j + 1 >= n:
                        raise syntax(source, line, col, "Unterminated string")
                    e = text[j + 1]
                    if e in '"\\/bfnrt':
                        j += 2
                    elif e == "u":
                        digits = text[j + 2:j + 6]
                        if len(digits) != 4 or any(h not in "0123456789abcdefABCDEF" for h in digits):
                            raise syntax(source, line, j - line_start + 1, "Invalid unicode escape")
                        j += 6
                    else:
                        raise syntax(source, line, j - line_start + 1, "Invalid string escape")
                elif ord(d) < 0x20:
                    raise syntax(source, line, j - line_start + 1, "Control character in string")
                else:
                    j += 1
            try:
                value = json.loads(text[i:j + 1])
            except ValueError:
                raise syntax(source, line, col, "Invalid string literal") from None
            tokens.append(Token("str", value, loc))
            i = j + 1
        else:
            two = text[i:i + 2]
            if two in TWO_CHAR_OPS:
                tokens.append(Token("op", two, loc))
                i += 2
            elif c in ONE_CHAR_OPS:
                tokens.append(Token("op", c, loc))
                i += 1
            else:
                raise syntax(source, line, col, "Illegal token %r" % c)


# ---------------------------------------------------------------- AST

class Node:
    __slots__ = ()


class Proc(Node):
    __slots__ = ("name", "params", "body", "loc")

    def __init__(self, name, params, body, loc):
        self.name, self.params, self.body, self.loc = name, params, body, loc


class Param(Node):
    __slots__ = ("name", "type", "default", "has_default", "loc")

    def __init__(self, name, type_, default, has_default, loc):
        self.name, self.type, self.default, self.has_default, self.loc = (
            name, type_, default, has_default, loc)


class Block(Node):
    __slots__ = ("stmts", "loc")

    def __init__(self, stmts, loc):
        self.stmts, self.loc = stmts, loc


class Stmt(Node):
    """Generic statement: `kind` selects semantics; `a` holds operands."""
    __slots__ = ("kind", "loc", "a", "extra")

    def __init__(self, kind, loc, a=(), extra=None):
        self.kind, self.loc, self.a, self.extra = kind, loc, a, extra


class Expr(Node):
    __slots__ = ("kind", "loc", "value", "args", "type")

    def __init__(self, kind, loc, value=None, args=()):
        self.kind, self.loc, self.value, self.args = kind, loc, value, args
        self.type = None


class Arg(Node):
    __slots__ = ("name", "expr", "loc")

    def __init__(self, name, expr, loc):
        self.name, self.expr, self.loc = name, expr, loc


# ---------------------------------------------------------------- parser

OPERAND_COUNTS = {"receive": 3, "move": 4, "reserve": 4, "release": 2, "ship": 2,
                  "record_delivery": 2}

BINARY_LEVELS = (("||",), ("&&",), ("==", "!="), ("<", "<=", ">", ">="),
                 ("+", "-"), ("*", "/", "%"))


class Parser:
    def __init__(self, source):
        self.source = source
        self.tokens = tokenize(source)
        self.pos = 0

    def peek(self, offset=0):
        return self.tokens[min(self.pos + offset, len(self.tokens) - 1)]

    def advance(self):
        tok = self.tokens[self.pos]
        if tok.kind != "eof":
            self.pos += 1
        return tok

    def fail(self, tok, message):
        _, line, col = tok.loc
        if tok.kind == "eof":
            message += " (found end of file)"
        else:
            message += " (found %r)" % (tok.value,)
        raise syntax(self.source, line, col, message)

    def is_op(self, value, offset=0):
        tok = self.peek(offset)
        return tok.kind == "op" and tok.value == value

    def is_kw(self, value, offset=0):
        tok = self.peek(offset)
        return tok.kind == "kw" and tok.value == value

    def expect_op(self, value):
        tok = self.peek()
        if tok.kind != "op" or tok.value != value:
            self.fail(tok, "Expected %r" % value)
        return self.advance()

    def expect_kw(self, value):
        tok = self.peek()
        if tok.kind != "kw" or tok.value != value:
            self.fail(tok, "Expected %r" % value)
        return self.advance()

    def expect_name(self):
        tok = self.peek()
        if tok.kind != "name":
            self.fail(tok, "Expected identifier")
        return self.advance()

    def expect_type(self):
        tok = self.peek()
        if tok.kind != "kw" or tok.value not in TYPES:
            self.fail(tok, "Expected type")
        return self.advance().value

    def parse_program(self):
        procs = []
        while self.peek().kind != "eof":
            procs.append(self.parse_proc())
        return procs

    def parse_proc(self):
        self.expect_kw("proc")
        name_tok = self.expect_name()
        self.expect_op("(")
        params = []
        if not self.is_op(")"):
            while True:
                params.append(self.parse_param())
                if self.is_op(","):
                    self.advance()
                    continue
                break
        self.expect_op(")")
        body = self.parse_block()
        return Proc(name_tok.value, params, body, name_tok.loc)

    def parse_param(self):
        name_tok = self.expect_name()
        self.expect_op(":")
        type_ = self.expect_type()
        if self.is_op("="):
            self.advance()
            return Param(name_tok.value, type_, self.parse_literal(), True, name_tok.loc)
        return Param(name_tok.value, type_, None, False, name_tok.loc)

    def parse_literal(self):
        tok = self.peek()
        if tok.kind == "int":
            self.advance()
            return tok.value
        if tok.kind == "op" and tok.value == "-" and self.peek(1).kind == "int":
            self.advance()
            return -self.advance().value
        if tok.kind == "str":
            self.advance()
            return tok.value
        if tok.kind == "kw" and tok.value in ("true", "false"):
            self.advance()
            return tok.value == "true"
        self.fail(tok, "Expected literal")

    def parse_block(self):
        open_tok = self.expect_op("{")
        stmts = []
        while not self.is_op("}"):
            if self.peek().kind == "eof":
                self.fail(self.peek(), "Expected '}'")
            stmts.append(self.parse_stmt())
        self.advance()
        return Block(stmts, open_tok.loc)

    def parse_operands(self, count):
        self.expect_op("(")
        operands = [self.parse_expr()]
        for _ in range(count - 1):
            self.expect_op(",")
            operands.append(self.parse_expr())
        self.expect_op(")")
        self.expect_op(";")
        return tuple(operands)

    def parse_stmt(self):
        tok = self.peek()
        loc = tok.loc
        if tok.kind == "name":
            name_tok = self.advance()
            args = self.parse_args()
            self.expect_op(";")
            return Stmt("call", loc, args, name_tok.value)
        if tok.kind != "kw":
            self.fail(tok, "Expected statement")
        kw = tok.value
        if kw == "let":
            self.advance()
            name_tok = self.expect_name()
            self.expect_op(":")
            type_ = self.expect_type()
            self.expect_op("=")
            expr = self.parse_expr()
            self.expect_op(";")
            return Stmt("let", loc, (expr,), (name_tok.value, type_, name_tok.loc))
        if kw == "set":
            self.advance()
            name_tok = self.expect_name()
            self.expect_op("=")
            expr = self.parse_expr()
            self.expect_op(";")
            return Stmt("set", loc, (expr,), (name_tok.value, name_tok.loc))
        if kw == "if":
            self.advance()
            self.expect_op("(")
            cond = self.parse_expr()
            self.expect_op(")")
            then = self.parse_block()
            other = None
            if self.is_kw("else"):
                self.advance()
                other = self.parse_block()
            return Stmt("if", loc, (cond,), (then, other))
        if kw == "while":
            self.advance()
            self.expect_op("(")
            cond = self.parse_expr()
            self.expect_op(")")
            return Stmt("while", loc, (cond,), self.parse_block())
        if kw == "transaction":
            self.advance()
            body = self.parse_block()
            rec_name = rec_block = rec_loc = None
            if self.is_kw("recover"):
                self.advance()
                self.expect_op("(")
                name_tok = self.expect_name()
                rec_name, rec_loc = name_tok.value, name_tok.loc
                self.expect_op(")")
                rec_block = self.parse_block()
            return Stmt("transaction", loc, (), (body, rec_name, rec_block, rec_loc))
        if kw in ("break", "continue", "return"):
            self.advance()
            self.expect_op(";")
            return Stmt(kw, loc)
        if kw in ("assert", "pause"):
            self.advance()
            expr = self.parse_expr()
            self.expect_op(";")
            return Stmt(kw, loc, (expr,))
        if kw == "emit":
            self.advance()
            name = self.parse_expr()
            self.expect_op("{")
            fields = []
            if not self.is_op("}"):
                while True:
                    key_tok = self.expect_name()
                    self.expect_op(":")
                    fields.append((key_tok.value, self.parse_expr(), key_tok.loc))
                    if self.is_op(";"):
                        self.advance()
                        if self.is_op("}"):
                            break
                        continue
                    break
            self.expect_op("}")
            self.expect_op(";")
            return Stmt("emit", loc, (name,), fields)
        if kw in OPERAND_COUNTS:
            self.advance()
            return Stmt(kw, loc, self.parse_operands(OPERAND_COUNTS[kw]))
        self.fail(tok, "Expected statement")

    def parse_args(self):
        self.expect_op("(")
        args = []
        if not self.is_op(")"):
            while True:
                tok = self.peek()
                if tok.kind == "name" and self.is_op("=", 1):
                    self.advance()
                    self.advance()
                    args.append(Arg(tok.value, self.parse_expr(), tok.loc))
                else:
                    args.append(Arg(None, self.parse_expr(), tok.loc))
                if self.is_op(","):
                    self.advance()
                    continue
                break
        self.expect_op(")")
        return args

    def parse_expr(self, level=0):
        if level == len(BINARY_LEVELS):
            return self.parse_unary()
        ops = BINARY_LEVELS[level]
        left = self.parse_expr(level + 1)
        while self.peek().kind == "op" and self.peek().value in ops:
            op_tok = self.advance()
            right = self.parse_expr(level + 1)
            left = Expr("binary", op_tok.loc, op_tok.value, (left, right))
        return left

    def parse_unary(self):
        tok = self.peek()
        if tok.kind == "op" and tok.value in ("!", "-"):
            self.advance()
            return Expr("unary", tok.loc, tok.value, (self.parse_unary(),))
        return self.parse_primary()

    def parse_primary(self):
        tok = self.peek()
        if tok.kind == "int":
            self.advance()
            return Expr("lit", tok.loc, tok.value)
        if tok.kind == "str":
            self.advance()
            return Expr("lit", tok.loc, tok.value)
        if tok.kind == "kw" and tok.value in ("true", "false"):
            self.advance()
            return Expr("lit", tok.loc, tok.value == "true")
        if tok.kind == "name":
            self.advance()
            if self.is_op("("):
                return Expr("call", tok.loc, tok.value, self.parse_args())
            return Expr("var", tok.loc, tok.value)
        if tok.kind == "op" and tok.value == "(":
            self.advance()
            expr = self.parse_expr()
            self.expect_op(")")
            return expr
        self.fail(tok, "Expected expression")


# ---------------------------------------------------------------- checker

def literal_type(value):
    if isinstance(value, bool):
        return "bool"
    if isinstance(value, int):
        return "int"
    return "string"


class Checker:
    def __init__(self, procs, program_source):
        self.proc_list = procs
        self.program_source = program_source
        self.procs = {}
        self.edges = {}

    def check(self):
        for proc in self.proc_list:
            if proc.name in BUILTINS:
                raise static(proc.loc, "Procedure name %r is a reserved builtin" % proc.name)
            if proc.name in self.procs:
                raise static(proc.loc, "Duplicate procedure %r" % proc.name)
            self.procs[proc.name] = proc
            seen = set()
            defaulted = False
            for param in proc.params:
                if param.name in seen:
                    raise static(param.loc, "Duplicate parameter %r" % param.name)
                seen.add(param.name)
                if param.has_default:
                    defaulted = True
                    if literal_type(param.default) != param.type:
                        raise static(param.loc, "Default value type mismatch for %r" % param.name)
                elif defaulted:
                    raise static(param.loc, "Required parameter after defaulted parameter")
        main = self.procs.get("main")
        if main is None:
            raise static((self.program_source, 1, 1), "Program has no main procedure")
        if main.params:
            raise static(main.loc, "main cannot have parameters")
        for proc in self.proc_list:
            self.check_proc(proc)
        self.check_recursion()
        return self.procs

    # -- scopes
    def lookup(self, name):
        for scope in reversed(self.scopes):
            if name in scope:
                return scope[name]
        return None

    def check_proc(self, proc):
        self.edges[proc.name] = []
        self.current = proc
        self.loops = 0
        self.scopes = [{p.name: p.type for p in proc.params}]
        for stmt in proc.body.stmts:
            self.stmt(stmt)

    def block(self, block, scope=None):
        self.scopes.append(scope if scope is not None else {})
        for stmt in block.stmts:
            self.stmt(stmt)
        self.scopes.pop()

    def want(self, expr, type_, what):
        actual = self.expr(expr)
        if actual != type_:
            raise static(expr.loc, "%s must be %s, not %s" % (what, type_, actual))

    def stmt(self, s):
        kind = s.kind
        if kind == "let":
            name, type_, name_loc = s.extra
            actual = self.expr(s.a[0])
            if name in self.scopes[-1]:
                raise static(name_loc, "Duplicate declaration of %r" % name)
            if actual != type_:
                raise static(s.a[0].loc, "Cannot initialize %s %r with %s" % (type_, name, actual))
            self.scopes[-1][name] = type_
        elif kind == "set":
            name, name_loc = s.extra
            target = self.lookup(name)
            if target is None:
                raise static(name_loc, "Unknown variable %r" % name)
            if target == "error":
                raise static(name_loc, "Cannot assign recovery binding %r" % name)
            actual = self.expr(s.a[0])
            if actual != target:
                raise static(s.a[0].loc, "Cannot assign %s to %s %r" % (actual, target, name))
        elif kind == "if":
            self.want(s.a[0], "bool", "Condition")
            then, other = s.extra
            self.block(then)
            if other is not None:
                self.block(other)
        elif kind == "while":
            self.want(s.a[0], "bool", "Condition")
            self.loops += 1
            self.block(s.extra)
            self.loops -= 1
        elif kind == "transaction":
            body, rec_name, rec_block, _ = s.extra
            self.block(body)
            if rec_block is not None:
                self.block(rec_block, {rec_name: "error"})
        elif kind in ("break", "continue"):
            if self.loops == 0:
                raise static(s.loc, "%s outside loop" % kind)
        elif kind == "return":
            pass
        elif kind == "assert":
            self.want(s.a[0], "bool", "Assertion")
        elif kind == "pause":
            self.want(s.a[0], "string", "Pause label")
        elif kind == "emit":
            self.want(s.a[0], "string", "Event name")
            seen = set()
            for key, value, key_loc in s.extra:
                if key in seen:
                    raise static(key_loc, "Duplicate emit key %r" % key)
                seen.add(key)
                if self.expr(value) not in TYPES:
                    raise static(value.loc, "Emit payload must be int, bool or string")
        elif kind in OPERAND_COUNTS:
            signature = {
                "receive": ("string", "string", "int"),
                "move": ("string", "string", "string", "int"),
                "reserve": ("string", "string", "string", "int"),
                "release": ("string", "int"),
                "ship": ("string", "int"),
                "record_delivery": ("string", "string"),
            }[kind]
            for operand, type_ in zip(s.a, signature):
                self.want(operand, type_, "%s operand" % kind)
        elif kind == "call":
            self.call_stmt(s)
        else:  # pragma: no cover
            raise AssertionError(kind)

    def call_stmt(self, s):
        name = s.extra
        if name in BUILTINS:
            raise static(s.loc, "Builtin %r cannot be used as a statement" % name)
        proc = self.procs.get(name)
        if proc is None:
            raise static(s.loc, "Unknown procedure %r" % name)
        params = {p.name: p for p in proc.params}
        bound = set()
        named_seen = False
        positional = 0
        for arg in s.a:
            if arg.name is None:
                if named_seen:
                    raise static(arg.loc, "Positional argument after named argument")
                if positional >= len(proc.params):
                    raise static(arg.loc, "Too many arguments to %r" % name)
                param = proc.params[positional]
                positional += 1
            else:
                named_seen = True
                param = params.get(arg.name)
                if param is None:
                    raise static(arg.loc, "Unknown argument %r for %r" % (arg.name, name))
                if param.name in bound:
                    raise static(arg.loc, "Argument %r bound more than once" % arg.name)
            bound.add(param.name)
            actual = self.expr(arg.expr)
            if actual != param.type:
                raise static(arg.expr.loc, "Argument %r must be %s, not %s"
                             % (param.name, param.type, actual))
        for param in proc.params:
            if param.name not in bound and not param.has_default:
                raise static(s.loc, "Missing argument %r for %r" % (param.name, name))
        self.edges[self.current.name].append((name, s.loc))

    def expr(self, e):
        e.type = self._expr(e)
        return e.type

    def _expr(self, e):
        kind = e.kind
        if kind == "lit":
            return literal_type(e.value)
        if kind == "var":
            type_ = self.lookup(e.value)
            if type_ is None:
                raise static(e.loc, "Unknown variable %r" % e.value)
            if type_ == "error":
                raise static(e.loc, "Recovery binding %r can only be used with code()" % e.value)
            return type_
        if kind == "unary":
            operand = self.expr(e.args[0])
            want = "bool" if e.value == "!" else "int"
            if operand != want:
                raise static(e.loc, "Operator %s requires %s" % (e.value, want))
            return want
        if kind == "binary":
            op = e.value
            left = self.expr(e.args[0])
            right = self.expr(e.args[1])
            if op in ("&&", "||"):
                if left != "bool" or right != "bool":
                    raise static(e.loc, "Operator %s requires bool operands" % op)
                return "bool"
            if op in ("==", "!="):
                if left != right:
                    raise static(e.loc, "Equality requires identical types")
                return "bool"
            if op in ("<", "<=", ">", ">="):
                if left != right or left not in ("int", "string"):
                    raise static(e.loc, "Ordering requires int/int or string/string")
                return "bool"
            if op == "+":
                if left != right or left not in ("int", "string"):
                    raise static(e.loc, "+ requires int/int or string/string")
                return left
            if left != "int" or right != "int":
                raise static(e.loc, "Operator %s requires int operands" % op)
            return "int"
        if kind == "call":
            name = e.value
            if name not in BUILTINS:
                if name in self.procs:
                    raise static(e.loc, "Procedure %r cannot be used as an expression" % name)
                raise static(e.loc, "Unknown builtin %r" % name)
            params, result = BUILTINS[name]
            for arg in e.args:
                if arg.name is not None:
                    raise static(arg.loc, "Builtin %r accepts positional arguments only" % name)
            if len(e.args) != len(params):
                raise static(e.loc, "Builtin %r expects %d arguments" % (name, len(params)))
            if name == "code":
                target = e.args[0].expr
                if target.kind != "var" or self.lookup(target.value) != "error":
                    raise static(target.loc, "code() requires a recovery binding")
                target.type = "error"
                return result
            for arg, type_ in zip(e.args, params):
                actual = self.expr(arg.expr)
                if actual != type_:
                    raise static(arg.expr.loc, "Builtin %r argument must be %s, not %s"
                                 % (name, type_, actual))
            return result
        raise AssertionError(kind)  # pragma: no cover

    def check_recursion(self):
        state = {}

        def visit(name):
            state[name] = 1
            for callee, loc in self.edges.get(name, ()):
                mark = state.get(callee, 0)
                if mark == 1:
                    raise static(loc, "Recursive call to %r" % callee)
                if mark == 0:
                    visit(callee)
            state[name] = 2

        for proc in self.proc_list:
            if state.get(proc.name, 0) == 0:
                visit(proc.name)


def compile_unit(program, library):
    """Parse library (if any) then program, and validate them as one unit."""
    procs = []
    if library is not None:
        procs.extend(Parser(library).parse_program())
    procs.extend(Parser(program).parse_program())
    return Checker(procs, program).check()

"""Tree-walking evaluator with journaled transactions and deterministic replay."""
import hashlib
import json

from .errors import DomainError, PauseExit, StockroomError

STEP_LIMIT = 20000
CALL_LIMIT = 32
TXN_LIMIT = 32

BREAK, CONTINUE, RETURN = 1, 2, 3
_MISSING = object()


class CheckpointMismatch(Exception):
    """Replay diverged from the recorded continuation."""


class ErrorValue:
    __slots__ = ("code",)

    def __init__(self, code):
        self.code = code


class Frame:
    __slots__ = ("name", "scopes")

    def __init__(self, name, scope):
        self.name = name
        self.scopes = [scope]


def canonical(value):
    return json.dumps(value, sort_keys=True, separators=(",", ":"),
                      ensure_ascii=True, allow_nan=False)


class Interpreter:
    """Executes a checked compilation unit.

    Durable mode replays the program from main using the checkpoint's log of
    carrier observations until `target` pauses have been passed, then continues
    live. Local state is therefore reconstructed deterministically; the carrier
    is never contacted during the replayed prefix.
    """

    def __init__(self, procs, warehouses, carrier=None, durable=False,
                 target=0, observations=None, expected=None):
        self.procs = procs
        self.warehouses = warehouses
        self.holds = {}
        self.events = []
        self.deliveries = {}
        self.steps = 0
        self.committed = 0
        self.rolled_back = 0
        self.journal = []
        self.txn_depth = 0
        self.frames = []
        self.carrier = carrier          # CarrierLink or None
        self.durable = durable
        self.target = target
        self.pause_count = 0
        self.expected = expected        # verification data for the target pause
        self.observations = list(observations or [])
        self.replay_index = 0
        self.replaying = target > 0
        self.dispatch = {
            "let": self.s_let, "set": self.s_set, "if": self.s_if,
            "while": self.s_while, "transaction": self.s_transaction,
            "break": self.s_break, "continue": self.s_continue,
            "return": self.s_return, "assert": self.s_assert, "emit": self.s_emit,
            "receive": self.s_receive, "move": self.s_move, "reserve": self.s_reserve,
            "release": self.s_release, "ship": self.s_ship, "call": self.s_call,
            "pause": self.s_pause, "record_delivery": self.s_record_delivery,
        }

    # ------------------------------------------------------------ helpers
    def stack(self):
        return [frame.name for frame in self.frames]

    def domain(self, code, message, loc):
        return DomainError(code, message, loc, self.stack())

    def fatal(self, category, message, loc):
        return StockroomError(category, message, loc, self.stack())

    def log(self, entry):
        if self.txn_depth:
            self.journal.append(entry)

    def lookup_scope(self, name):
        for scope in reversed(self.frames[-1].scopes):
            if name in scope:
                return scope
        raise AssertionError("unresolved variable " + name)  # checker guarantees

    # ------------------------------------------------------------ run
    def run(self):
        main = self.procs["main"]
        self.frames.append(Frame("main", {}))
        try:
            self.exec_stmts(main.body.stmts)
        finally:
            self.frames.pop()
        if self.replaying:
            raise CheckpointMismatch("execution finished before the saved pause")

    def result(self):
        return {
            "warehouses": self.warehouses,
            "holds": self.holds,
            "events": [{"id": i, "name": name, "data": data}
                       for i, (name, data) in enumerate(self.events, 1)],
            "stats": {"steps": self.steps, "committed": self.committed,
                      "rolled_back": self.rolled_back},
            "deliveries": self.deliveries,
        }

    def digest(self, label):
        body = self.result()
        body["pause"] = [self.pause_count, label, self.txn_depth,
                         len(self.frames), self.replay_index]
        return hashlib.sha256(canonical(body).encode("utf-8")).hexdigest()

    # ------------------------------------------------------------ statements
    def exec_stmts(self, stmts):
        for stmt in stmts:
            if self.steps >= STEP_LIMIT:
                raise self.fatal("RUNTIME", "Step limit exceeded", stmt.loc)
            self.steps += 1
            signal = self.dispatch[stmt.kind](stmt)
            if signal:
                return signal
        return None

    def exec_block(self, block, scope=None):
        scopes = self.frames[-1].scopes
        scopes.append({} if scope is None else scope)
        try:
            return self.exec_stmts(block.stmts)
        finally:
            scopes.pop()

    def s_let(self, s):
        value = self.eval(s.a[0])
        self.frames[-1].scopes[-1][s.extra[0]] = value

    def s_set(self, s):
        value = self.eval(s.a[0])
        name = s.extra[0]
        scope = self.lookup_scope(name)
        if self.txn_depth:
            self.journal.append(("var", scope, name, scope[name]))
        scope[name] = value

    def s_if(self, s):
        then, other = s.extra
        if self.eval(s.a[0]):
            return self.exec_block(then)
        if other is not None:
            return self.exec_block(other)
        return None

    def s_while(self, s):
        cond = s.a[0]
        while self.eval(cond):
            signal = self.exec_block(s.extra)
            if signal == BREAK:
                break
            if signal == RETURN:
                return RETURN
        return None

    def s_break(self, s):
        return BREAK

    def s_continue(self, s):
        return CONTINUE

    def s_return(self, s):
        return RETURN

    def s_transaction(self, s):
        body, rec_name, rec_block, _ = s.extra
        if self.txn_depth >= TXN_LIMIT:
            raise self.fatal("RUNTIME", "Transaction nesting limit exceeded", s.loc)
        mark = len(self.journal)
        scope_depth = len(self.frames[-1].scopes)
        frame_depth = len(self.frames)
        self.txn_depth += 1
        try:
            signal = self.exec_block(body)
        except DomainError as error:
            self.txn_depth -= 1
            self.rollback(mark)
            del self.frames[frame_depth:]
            del self.frames[-1].scopes[scope_depth:]
            self.rolled_back += 1
            if rec_block is None:
                raise
            return self.exec_block(rec_block, {rec_name: ErrorValue(error.code)})
        except BaseException:
            self.txn_depth -= 1
            raise
        self.txn_depth -= 1
        self.committed += 1
        if not self.txn_depth:
            self.journal.clear()
        return signal

    def rollback(self, mark):
        journal = self.journal
        while len(journal) > mark:
            entry = journal.pop()
            kind = entry[0]
            if kind == "var":
                entry[1][entry[2]] = entry[3]
            elif kind == "stock":
                _, warehouse, sku, old = entry
                if old is _MISSING:
                    del self.warehouses[warehouse][sku]
                else:
                    self.warehouses[warehouse][sku] = old
            elif kind == "hold_new":
                del self.holds[entry[1]]
            elif kind == "hold_rem":
                self.holds[entry[1]]["remaining"] = entry[2]
            elif kind == "event":
                self.events.pop()
            elif kind == "delivery":
                del self.deliveries[entry[1]]

    def s_assert(self, s):
        if not self.eval(s.a[0]):
            raise self.domain("ASSERT", "Assertion failed", s.loc)

    def s_emit(self, s):
        name = self.eval(s.a[0])
        data = {}
        for key, expr, _ in s.extra:
            data[key] = self.eval(expr)
        self.events.append((name, data))
        self.log(("event",))

    def s_call(self, s):
        proc = self.procs[s.extra]
        params = proc.params
        scope = {}
        index = 0
        for arg in s.a:
            value = self.eval(arg.expr)
            if arg.name is None:
                scope[params[index].name] = value
                index += 1
            else:
                scope[arg.name] = value
        bound = {}
        for param in params:
            bound[param.name] = scope[param.name] if param.name in scope else param.default
        if len(self.frames) >= CALL_LIMIT:
            raise self.fatal("RUNTIME", "Call depth limit exceeded", s.loc)
        self.frames.append(Frame(proc.name, bound))
        try:
            self.exec_stmts(proc.body.stmts)
        finally:
            self.frames.pop()
        return None

    def s_pause(self, s):
        label = self.eval(s.a[0])
        if not self.durable:
            return None
        self.pause_count += 1
        if self.replaying:
            if self.pause_count < self.target:
                return None
            expected = self.expected
            if (label != expected["label"] or self.steps != expected["steps"]
                    or self.digest(label) != expected["digest"]
                    or self.replay_index != len(self.observations)):
                raise CheckpointMismatch("replayed state does not match the checkpoint")
            self.replaying = False
            return None
        raise PauseExit(label)

    # ------------------------------------------------------------ inventory ops
    def qty(self, value, loc):
        if value <= 0:
            raise self.domain("QUANTITY", "Quantity must be positive", loc)

    def name(self, value, what, loc):
        if value == "":
            raise self.domain("NAME", "%s must be nonempty" % what, loc)

    def warehouse(self, name, loc):
        stock = self.warehouses.get(name)
        if stock is None:
            raise self.domain("WAREHOUSE", "Unknown warehouse %r" % name, loc)
        return stock

    def hold(self, hold_id, loc):
        record = self.holds.get(hold_id)
        if record is None:
            raise self.domain("HOLD", "Unknown hold %r" % hold_id, loc)
        return record

    def held(self, warehouse, sku):
        return sum(h["remaining"] for h in self.holds.values()
                   if h["warehouse"] == warehouse and h["sku"] == sku)

    def available_of(self, warehouse, sku):
        return self.warehouses[warehouse].get(sku, 0) - self.held(warehouse, sku)

    def set_stock(self, warehouse, sku, value):
        stock = self.warehouses[warehouse]
        if self.txn_depth:
            self.journal.append(("stock", warehouse, sku, stock.get(sku, _MISSING)))
        stock[sku] = value

    def s_receive(self, s):
        warehouse, sku, qty = [self.eval(e) for e in s.a]
        self.qty(qty, s.loc)
        self.name(sku, "SKU", s.loc)
        stock = self.warehouse(warehouse, s.loc)
        self.set_stock(warehouse, sku, stock.get(sku, 0) + qty)

    def s_move(self, s):
        source, dest, sku, qty = [self.eval(e) for e in s.a]
        self.qty(qty, s.loc)
        self.name(sku, "SKU", s.loc)
        src = self.warehouse(source, s.loc)
        dst = self.warehouse(dest, s.loc)
        if source == dest:
            raise self.domain("SAME_WAREHOUSE", "Source and destination are equal", s.loc)
        if self.available_of(source, sku) < qty:
            raise self.domain("SHORTAGE", "Insufficient available stock", s.loc)
        self.set_stock(source, sku, src.get(sku, 0) - qty)
        self.set_stock(dest, sku, dst.get(sku, 0) + qty)

    def s_reserve(self, s):
        hold_id, warehouse, sku, qty = [self.eval(e) for e in s.a]
        self.qty(qty, s.loc)
        self.name(hold_id, "Hold ID", s.loc)
        self.name(sku, "SKU", s.loc)
        self.warehouse(warehouse, s.loc)
        if hold_id in self.holds:
            raise self.domain("DUPLICATE_HOLD", "Hold %r already exists" % hold_id, s.loc)
        if self.available_of(warehouse, sku) < qty:
            raise self.domain("SHORTAGE", "Insufficient available stock", s.loc)
        self.holds[hold_id] = {"warehouse": warehouse, "sku": sku, "remaining": qty}
        self.log(("hold_new", hold_id))

    def reduce_hold(self, s, ship):
        hold_id, qty = [self.eval(e) for e in s.a]
        self.qty(qty, s.loc)
        self.name(hold_id, "Hold ID", s.loc)
        record = self.hold(hold_id, s.loc)
        if qty > record["remaining"]:
            raise self.domain("SHORTAGE", "Quantity exceeds hold remaining", s.loc)
        if self.txn_depth:
            self.journal.append(("hold_rem", hold_id, record["remaining"]))
        record["remaining"] -= qty
        if ship:
            stock = self.warehouses[record["warehouse"]]
            self.set_stock(record["warehouse"], record["sku"],
                           stock.get(record["sku"], 0) - qty)

    def s_release(self, s):
        self.reduce_hold(s, False)

    def s_ship(self, s):
        self.reduce_hold(s, True)

    def s_record_delivery(self, s):
        key, receipt = [self.eval(e) for e in s.a]
        self.name(key, "Delivery key", s.loc)
        self.name(receipt, "Receipt", s.loc)
        if key in self.deliveries:
            raise self.domain("ALREADY_POSTED", "Delivery %r already recorded" % key, s.loc)
        record = self.carrier_lookup(key, s.loc)
        if record is None or record["receipt"] != receipt:
            raise self.domain("CARRIER_CONFLICT", "No carrier acceptance with that receipt", s.loc)
        for suffix, sku_field in ((".a", "sku_a"), (".b", "sku_b")):
            hold = self.holds.get(key + suffix)
            if (hold is None or hold["remaining"] != 0
                    or hold["warehouse"] != record["warehouse"]
                    or hold["sku"] != record[sku_field]):
                raise self.domain("HOLD", "Hold %r does not match the carrier record"
                                  % (key + suffix), s.loc)
        self.deliveries[key] = {field: record[field] for field in
                                ("receipt", "warehouse", "sku_a", "qty_a", "sku_b", "qty_b")}
        self.log(("delivery", key))

    # ------------------------------------------------------------ carrier
    def observe(self, request, loc, perform):
        """Return a recorded observation during replay, else perform and record."""
        if self.replaying:
            if self.replay_index >= len(self.observations):
                raise CheckpointMismatch("checkpoint carrier log is exhausted")
            entry = self.observations[self.replay_index]
            if entry.get("request") != request:
                raise CheckpointMismatch("carrier request diverged during replay")
            self.replay_index += 1
        else:
            if self.carrier is None:
                raise self.fatal("IO", "Carrier access requires --carrier", loc)
            entry = perform()
            entry["request"] = request
            self.observations.append(entry)
            self.replay_index = len(self.observations)
        if "failure" in entry:
            code, message = entry["failure"]
            raise self.domain(code, message, loc)
        return entry["response"]

    def carrier_lookup(self, key, loc):
        return self.observe(["lookup", key], loc,
                            lambda: {"response": self.carrier.lookup(key, self, loc)})

    def carrier_send(self, args, loc):
        return self.observe(["submit"] + list(args), loc,
                            lambda: self.carrier.submit(args, self, loc))

    # ------------------------------------------------------------ expressions
    def eval(self, e):
        kind = e.kind
        if kind == "lit":
            return e.value
        if kind == "var":
            name = e.value
            for scope in reversed(self.frames[-1].scopes):
                if name in scope:
                    return scope[name]
            raise AssertionError(name)
        if kind == "binary":
            op = e.value
            if op == "&&":
                return self.eval(e.args[0]) and self.eval(e.args[1])
            if op == "||":
                return self.eval(e.args[0]) or self.eval(e.args[1])
            left = self.eval(e.args[0])
            right = self.eval(e.args[1])
            if op == "+":
                return left + right
            if op == "-":
                return left - right
            if op == "*":
                return left * right
            if op == "==":
                return left == right
            if op == "!=":
                return left != right
            if op == "<":
                return left < right
            if op == "<=":
                return left <= right
            if op == ">":
                return left > right
            if op == ">=":
                return left >= right
            if right == 0:
                raise self.fatal("RUNTIME", "Division by zero", e.loc)
            quotient = abs(left) // abs(right)
            if (left < 0) != (right < 0):
                quotient = -quotient
            if op == "/":
                return quotient
            return left - quotient * right
        if kind == "unary":
            value = self.eval(e.args[0])
            return (not value) if e.value == "!" else -value
        if kind == "call":
            return self.builtin(e)
        raise AssertionError(kind)

    def builtin(self, e):
        name = e.value
        if name == "code":
            return self.eval(e.args[0].expr).code
        args = [self.eval(arg.expr) for arg in e.args]
        loc = e.loc
        if name in ("onhand", "available"):
            warehouse, sku = args
            stock = self.warehouse(warehouse, loc)
            self.name(sku, "SKU", loc)
            if name == "onhand":
                return stock.get(sku, 0)
            return self.available_of(warehouse, sku)
        if name == "remaining":
            self.name(args[0], "Hold ID", loc)
            return self.hold(args[0], loc)["remaining"]
        if name == "len":
            return len(args[0])
        if name == "delivered":
            self.name(args[0], "Delivery key", loc)
            return args[0] in self.deliveries
        if name == "carrier_send":
            key, warehouse, sku_a, qty_a, sku_b, qty_b = args
            for value, what in ((key, "Key"), (warehouse, "Warehouse"),
                                (sku_a, "SKU"), (sku_b, "SKU")):
                self.name(value, what, loc)
            self.qty(qty_a, loc)
            self.qty(qty_b, loc)
            self.warehouse(warehouse, loc)
            return self.carrier_send(args, loc)
        key = args[0]
        self.name(key, "Carrier key", loc)
        record = self.carrier_lookup(key, loc)
        if name == "carrier_receipt":
            return "" if record is None else record["receipt"]
        if name == "carrier_warehouse":
            return "" if record is None else record["warehouse"]
        if name == "carrier_matches":
            return record is not None and [
                record["warehouse"], record["sku_a"], record["qty_a"],
                record["sku_b"], record["qty_b"]] == args[1:]
        raise AssertionError(name)

