def literal_type(value):
    if isinstance(value, bool):
        return "bool"
    if isinstance(value, int):
        return "int"
    return "string"


class Checker:
    def __init__(self, procs, program_source):
        self.proc_list = procs
        self.program_source = program_source
        self.procs = {}
        self.edges = {}

    def check(self):
