        def visit(name):
            state[name] = 1
            for callee, loc in self.edges.get(name, ()):
                mark = state.get(callee, 0)
                if mark == 1:
                    raise static(loc, "Recursive call to %r" % callee)
                if mark == 0:
                    visit(callee)
            state[name] = 2

        for proc in self.proc_list:
